<template><div class="page-shell"><div class="page-title-row"><div><h1 class="page-title">模拟状态数据接入</h1><p class="page-subtitle">通过表单模拟 IoT 粮情、气象灾害与道路交通数据，覆盖课程报告中的典型风险测试场景</p></div><el-tag type="warning" effect="plain" round>模拟数据模式</el-tag></div><el-tabs v-model="tab"><el-tab-pane label="IoT 粮情" name="iot"><CrudManager title="温湿度采集记录" endpoint="/state/iot" :columns="iotColumns" :fields="iotFields" :can-create="auth.user?.role!=='DISPATCHER'" :can-edit="false" :can-delete="auth.isAdmin"/></el-tab-pane><el-tab-pane label="气象风险" name="weather"><CrudManager title="气象预警记录" endpoint="/state/weather" :columns="weatherColumns" :fields="weatherFields" :can-create="auth.isAdmin" :can-edit="false" :can-delete="auth.isAdmin"/></el-tab-pane><el-tab-pane label="交通状态" name="traffic"><CrudManager title="交通状态记录" endpoint="/state/traffic" :columns="trafficColumns" :fields="trafficFields" :can-create="auth.isAdmin" :can-edit="false" :can-delete="auth.isAdmin"/></el-tab-pane></el-tabs></div></template>
<script setup>
import { onMounted,ref } from 'vue';import api from '../api/client';import CrudManager from '../components/CrudManager.vue';import { useAuthStore } from '../stores/auth';const auth=useAuthStore(),tab=ref('iot'),nodes=ref([]),routes=ref([]);onMounted(async()=>{[nodes.value,routes.value]=await Promise.all([api.get('/nodes'),api.get('/routes')])});const opts=a=>a.map(x=>({value:x.id,label:x.name}));
const iotColumns=[{prop:'nodeName',label:'节点',width:190},{prop:'temperature',label:'温度(℃)'},{prop:'humidity',label:'湿度(%)'},{prop:'collectedAt',label:'采集时间',width:180,formatter:v=>v?.replace('T',' ')}],iotFields=[{prop:'nodeId',label:'节点',type:'select',options:()=>opts(nodes.value),required:true},{prop:'temperature',label:'温度(℃)',type:'number',required:true},{prop:'humidity',label:'湿度(%)',type:'number',required:true},{prop:'collectedAt',label:'采集时间',type:'datetime'}];
const weatherColumns=[{prop:'region',label:'影响区域'},{prop:'disasterType',label:'灾害类型'},{prop:'warningLevel',label:'预警级别'},{prop:'rainfall',label:'降雨量(mm)'},{prop:'windLevel',label:'风力等级'},{prop:'publishedAt',label:'发布时间',width:180,formatter:v=>v?.replace('T',' ')}],weatherFields=[{prop:'region',label:'影响区域',required:true},{prop:'disasterType',label:'灾害类型',required:true},{prop:'warningLevel',label:'预警级别',required:true},{prop:'rainfall',label:'降雨量(mm)',type:'number'},{prop:'windLevel',label:'风力等级'},{prop:'publishedAt',label:'发布时间',type:'datetime'}];
const trafficColumns=[{prop:'routeName',label:'关联线路',width:190},{prop:'roadName',label:'路段名称',width:180},{prop:'status',label:'通行状态',tag:true},{prop:'congestionLevel',label:'拥堵说明'},{prop:'recordedAt',label:'更新时间',width:180,formatter:v=>v?.replace('T',' ')}],trafficFields=[{prop:'routeId',label:'关联线路',type:'select',options:()=>opts(routes.value),required:true},{prop:'roadName',label:'路段名称'},{prop:'status',label:'通行状态',type:'select',options:[{value:'NORMAL',label:'正常'},{value:'CONGESTED',label:'拥堵'},{value:'CLOSED',label:'封闭'}],required:true},{prop:'congestionLevel',label:'拥堵/封闭说明'},{prop:'recordedAt',label:'更新时间',type:'datetime'}];
</script>
